// GENERATED by scripts/build-mcp-app.mjs. Do not edit: change the sources and run `npm run mcp:app`.

/** The plugin's static files (skills, README), keyed by path inside the plugin. Source: plugin/. */
export const PLUGIN_FILES: Record<string, string> = {
  "README.md": "# Portfolio\n\nSee your fund's dashboards inside Claude or ChatGPT, and ask questions about what you are\nlooking at: the portfolio, a company and its KPIs, the financial statements, and LP capital.\n\nThis package is built by your fund's own Portfolio deployment. Its connector points at that\ndeployment and nowhere else.\n\n## Use it\n\nConnect the connector that comes with this plugin, sign in with your Portfolio account, and\napprove the connection. Then start with:\n\n- **\"What can you do?\"** — opens your home dashboard: the dashboards you can open, the ones you\n  saved, and questions to try for each area your access covers. Click any of them.\n\nOr ask in plain words:\n\n- \"Show me the portfolio.\"\n- \"Open the dashboard for Meridian Robotics.\"\n- \"Pull up the balance sheet for Fund I, last quarter.\"\n- \"Who has funded their capital calls?\"\n- \"Save this as Q3 LP review.\"\n- \"Open my Q3 LP review.\"\n\nA dashboard opens in the conversation. Click a company to drill in, change the period, or\nexpand it to full screen. Ask a follow-up and the assistant answers from the same figures.\n\nA saved dashboard keeps the view and its filters, never the numbers, so it always opens on\ncurrent data. Saved dashboards live in your Portfolio deployment, which is why they are there\nin any new conversation and in either assistant.\n\n## What you can see\n\nYou see what your Portfolio account can see, and nothing more. The assistant acts as you: if\nyour access does not include fund accounting or LP capital, those dashboards are refused for\nyou here exactly as they are in the app. An admin can switch assistant access off for the whole\nfund at any time in Settings.\n\n## Data\n\nWhen you ask for a dashboard or a figure, the assistant requests it from your fund's Portfolio\ndeployment over an encrypted connection, signed in as you. The figures are sent to the\nassistant you are using (Claude or ChatGPT) so it can show and discuss them, under that\nprovider's terms for your account. This plugin itself stores nothing and contains no\ncredentials. It does not send your fund's data anywhere else.\n\n## Prompts\n\nYour assistant's prompt menu (in Claude, the + menu or `/` in Claude Code) lists ready-made\nrequests from your deployment: *Get started*, *Portfolio review*, *Company check-in*,\n*Quarter-end review*, *LP capital status*, *Draft a forecast* and *Budget variance* — only the\nones your access covers. Pick one, fill in the company or fund, and send.\n\n## Skills\n\n- **fund-dashboards**: showing, opening and saving the four dashboards.\n- **fund-analysis**: answering questions from the fund's records with the right tool and the\n  fund's own definitions.\n",
  "skills/fund-analysis/SKILL.md": "---\nname: fund-analysis\ndescription: >\n  This skill should be used when the user asks a question about their fund that the Portfolio\n  connector can answer from the fund's own records: \"what is our TVPI\", \"how much have we\n  called\", \"what did we invest in Acme\", \"which companies are marked below cost\", \"what is\n  Acme's runway\", \"how much has each LP funded\", \"what is our net income this year\", \"do our\n  books agree with the administrator\", \"what did Acme say in their last update\" — and when the\n  user wants an LP document as a file: \"send me Cranmore's capital account statement\", \"a PDF of\n  the report card for Aldis\".\nmetadata:\n  version: \"1.1.0\"\n---\n\n# Answering questions about the fund\n\nThe Portfolio connector reads the fund's own tracker and books. Answer from it, not from\nmemory or estimates, and say what the figure is \"as of\".\n\nIf the user wants to *look at* something rather than get an answer, show a dashboard instead\n(the `fund-dashboards` skill).\n\n## Which tool answers what\n\n| Question | Tool |\n| --- | --- |\n| Which funds and SPVs exist | `list_vehicles` |\n| Which companies we hold, by stage, industry or status | `list_companies` |\n| One company: what it does, why we invested, cost, value, MOIC | `company_detail` |\n| Every position with cost, fair value, MOIC and share of the portfolio | `portfolio_summary` |\n| Committed, called, distributed, NAV, DPI, TVPI per vehicle | `fund_performance` |\n| A company's KPIs over time | `company_metrics` |\n| What a company reported in its updates | `get_updates` |\n| The raw investment transactions | `list_investments` |\n| LP positions as the books say today | `lp_live_report` |\n| LP positions as the administrator reported them | `lp_snapshot` |\n| Whether the books agree with the administrator | `lp_reconcile_snapshot` |\n| One LP's capital account statement | `lp_statement` |\n| One LP's capital account statement **as a PDF** | `lp_statement_pdf` |\n| An investor's report card (every vehicle aggregated) **as a PDF** | `lp_report_card_pdf` |\n| Capital calls and who has funded them (including \"says wired\" from the LP portal) | `lp_capital_calls` |\n| Balance sheet, income statement, trial balance | `financial_statements` |\n| Budget and forecast against actuals | `forecast_variance`, `forecast_series` |\n| A forecast's balance sheet, or a management company's Capital planning | `forecast_series` (`balanceSheet`, `capitalPlanning`) |\n| A forecast **as an Excel model** with live formulas | `forecast_workbook` |\n\nThe PDF tools and `forecast_workbook` return a link, not the document. Give the user the link as a link, say it\nworks for an hour and only for them, and do not try to open or summarize it — call\n`lp_statement` or `lp_live_report` for the figures. A statement is per LP entity and per vehicle;\nif the name matches several entities, ask which.\n\nOnly the tools the user's access allows are listed for them. If a tool here is not available,\nthe user's access does not include that area: say so, and do not look for another route to the\nsame figures.\n\n## The fund's definitions\n\nUse these exactly. They are how the app itself computes the figures.\n\n- **Paid-in capital is called capital.** Capital counts when it is called, whether or not the\n  LP has funded it yet. Paid-in is the denominator of DPI, RVPI and TVPI.\n- **Sum first, then take the ratio.** A fund's TVPI is total value over total paid-in, never an\n  average of each LP's or each vehicle's TVPI. The same holds for DPI, RVPI and MOIC.\n- **DPI** is distributions over paid-in. **RVPI** is NAV over paid-in. **TVPI** is their sum.\n- **MOIC** on a position is fair value plus realized proceeds, over cost.\n- **IRR** values come back as fractions: 0.214 is 21.4%.\n- **An investor may hold through several entities.** LP positions are per entity and per\n  vehicle. To report on an investor, sum their entities, then compute ratios.\n- **A snapshot and the live report can differ.** A snapshot is what the administrator reported\n  as of a date. The live report is what the books say now. Never mix them in one answer, and\n  say which one a figure came from. If they differ, that difference is the finding:\n  `lp_reconcile_snapshot` shows it line by line.\n- **A balance sheet is as of a date; an income statement covers a period.** State the date or\n  the period with every statement figure.\n\n## How to answer\n\n- Lead with the figure and its \"as of\", then one sentence of context if it helps.\n- Quote figures as the tool returned them. Round only for readability, and never round a ratio\n  to hide a difference the user is asking about.\n- When a question spans several vehicles, say whether the answer covers all of them or one.\n- When a name matches more than one company or investor, ask which. Do not pick.\n- When a tool returns nothing for a period, say there is nothing recorded. Do not infer a zero.\n\n## Changes to the fund's records\n\nSome tools change the fund's records: recording an investment, posting a journal entry,\nclosing a period, saving a forecast. They are available only on a connection the user approved\nfor changes, and only to users whose role allows them.\n\n- Never call one unless the user asked for that specific change in this conversation.\n- Before calling it, state exactly what will be recorded (the vehicle, the date, the amounts)\n  and get a yes.\n- After it, report what the tool returned, including any entry it created.\n- Closing a period is not reversible from here. Say that before asking for the yes.\n",
  "skills/fund-dashboards/SKILL.md": "---\nname: fund-dashboards\ndescription: >\n  This skill should be used when the user asks to see, show, open, chart, visualize or save a\n  view of their fund through the Portfolio connector: \"show me the portfolio\", \"open the\n  dashboard for Acme\", \"chart Acme's ARR\", \"pull up the balance sheet\", \"show the P&L for last\n  quarter\", \"who has funded\", \"show LP capital\", \"what dashboards do I have\", \"open my Q3 LP\n  dashboard\", \"save this dashboard as ...\", \"pin this\", \"delete that dashboard\" — and when the\n  user asks for help, \"what can you do?\", \"get started\", \"home\", or seems unsure what to ask.\nmetadata:\n  version: \"1.1.0\"\n---\n\n# Fund dashboards\n\nThe Portfolio connector can draw four dashboards in the conversation. Each is a tool that\nreturns the figures as text (for answering questions) and renders them as an interactive view\n(for the user to look at). Use them whenever the user wants to *see* something. For a question\nthat only needs a number, the `fund-analysis` skill applies instead.\n\n## Start at home\n\nWhen the user asks what you can do, asks for help or to get started, or is new and unsure what\nto ask, call `show_home`. It shows the dashboards they can open, their saved dashboards, and\nexample questions for the areas their access covers — and returns the same as text. Then give a\nshort, friendly overview in your own words with three suggestions to try first. Do not list tool\nnames. If the host cannot draw the view, the text is the whole answer.\n\n## Pick the dashboard\n\n| The user wants | Tool | Arguments |\n| --- | --- | --- |\n| Help, what you can do, a place to start | `show_home` | none |\n| The portfolio, holdings, the fund at a glance | `show_portfolio_dashboard` | `vehicle?`, `as_of?` |\n| One company: its position, KPIs, rounds | `show_company_dashboard` | `company`, `vehicle?` |\n| Balance sheet, income statement, cash flows, partners' capital | `show_financial_statements` | `vehicle?`, `period?`, `start?`, `end?` |\n| LPs, commitments, capital accounts | `show_lp_dashboard` | `vehicle?`, `as_of?` |\n| A capital call: who has paid, who says they wired, who still owes | `show_capital_calls` | `vehicle`, `call?` |\n| A dashboard the user names (\"my Q3 LP review\") | `open_dashboard` | `dashboard` |\n\nRules for the arguments:\n\n- Pass a company by the name the user said. If the tool answers that the name matches several\n  companies, or suggests near matches, ask the user which one. Do not guess.\n- `vehicle` is a fund or SPV. Leave it out to cover every vehicle the user can see. Financial\n  statements are per vehicle: if the tool answers \"Specify a vehicle\" it lists them, so ask the\n  user which, or call `list_vehicles`.\n- `period` for statements is one of `this_quarter`, `last_quarter`, `ytd`, `prior_year`, `itd`.\n  The default is `ytd`. For anything else pass `start` and `end` as `YYYY-MM-DD`.\n- Leave `as_of` out unless the user names a date. Without it the figures are current.\n\n## After the dashboard appears\n\nThe user is looking at the figures. Do not repeat them back.\n\n- Say what stands out in one or two sentences: the largest position, a company marked below\n  cost, an LP who has not funded, a balance sheet that does not balance.\n- Answer follow-up questions from the text the tool returned. It holds everything the view\n  shows, and it is what the fund's books and tracker say, so quote it exactly.\n- The user can drill in, change the period or sort inside the view without asking. When they\n  do, a note arrives saying what they are now viewing. Treat that as the current subject: \"what\n  is its MOIC?\" refers to the company on screen.\n- If the assistant shows only text and no view, present the same figures as a short table.\n\n## Open a saved dashboard\n\nWhen the user asks for a dashboard by a name:\n\n1. Call `open_dashboard` with that name.\n2. If it answers that there is no such dashboard, it lists the ones available. Offer the\n   closest, or call `list_dashboards` and show the list.\n\n`list_dashboards` returns three kinds: `standard` (always there), `mine` (the user saved it)\nand `shared` (a colleague shared it with the fund). When the user asks \"what dashboards do I\nhave\", list their own first, then the shared ones, then the standard ones.\n\n## Save a dashboard\n\nSave only when the user asks to save, keep or pin one. Never save on your own initiative.\n\n1. Use the name the user gave. If they gave none, ask for one.\n2. Call `save_dashboard` with `name`, the `view`, and the `arguments` of the dashboard on\n   screen. Each dashboard result carries its own `view` and `arguments`: copy them.\n3. Leave `as_of`, `start` and `end` out of the saved arguments unless the user wants the date\n   pinned. A dashboard saved without dates opens on current figures every time, which is\n   almost always what \"save this\" means. A `period` such as `last_quarter` is fine: it moves\n   with the calendar.\n4. Set `shared` to true only if the user asks to share it with their team.\n5. Confirm in one sentence, with the name to ask for next time.\n\nSaving under a name the user already has replaces that dashboard. Say so if that is what\nhappened.\n\nIf saving is refused because the connection is read-only, say that plainly: the user connected\nwith read-only access, and saving needs a connection that is allowed to make changes. They can\nreconnect the connector and approve write access, if their role in the fund allows it. Until\nthen they can still open any dashboard by asking for it.\n\n## Refusals\n\nA dashboard tool may answer that the user's access does not include an area (fund accounting,\nLP capital). That is the fund's own access control, set by its admin.\n\n- Tell the user which area they lack and that their fund's admin grants it.\n- Do not retry, and do not try to assemble the same figures from other tools.\n\nIf every tool answers that agent access is disabled for the fund, an admin has switched the\nconnector off in Settings. Say so and stop.\n",
  "skills/lp-quarterly-letter/references/examples.md": "# Examples\n\nGeneral examples for a fund that has not saved its own. Every company, person and figure here is\ninvented: copy the shape, never the facts.\n\n## Company update, a full quarter\n\n**Acme Robotics**\n*Warehouse picking robots for regional distributors.*\n\n- Status\n  Acme signed two new distributor contracts in the quarter and began its first deployment outside\n  its home region. Gross margin is still below plan because each installation needs an engineer on\n  site; the company expects remote setup to be ready next quarter, and we are helping it hire for\n  that.\n- Figures\n  - ARR: $1.2M at the end of Q3 2026 ($0.9M at the end of Q2)\n  - 14 sites live, up from 9\n\n## Company update, figures only\n\n**Birch Analytics**\n*Forecasting software for mid-sized retailers.*\n\n- Status\n  Birch reported Q3 2026 revenue of $640K and, by its own estimate, 18 months of runway.\n\n## Company update, nothing new\n\n**Northwind Health**\n*Scheduling software for outpatient clinics.*\n\n- Status\n  Northwind has not sent an update since our last letter.\n\n## Valuation change\n\nWe marked one position down this quarter. Northwind Health has not raised since our investment and\nits revenue fell short of the plan it raised on, so we reduced our carrying value to $250K, half\nof our cost.\n\n## New investment\n\nExample Ventures invested $500K in Zephyr Labs, which makes inventory software for independent\npharmacies, as part of a $3M seed round led by another investor. Zephyr was founded by Jane Doe,\nwho previously ran operations at a pharmacy chain.\n",
  "skills/lp-quarterly-letter/references/voice.md": "# Voice\n\nA general voice for an investor letter, for a fund that has not saved its own. A fund's own voice,\nlearned from its letters or written by its partners, replaces this one; `lp_letter_skill` returns\nwhichever applies.\n\n## Who is speaking\n\nThe partners, as \"we\", writing to investors who know the fund. Clear and specific, as candid about\nproblems as about progress, and never promotional.\n\n## Sentences\n\n- Short, plain sentences in the active voice.\n- Lead with the fact, then what it means.\n- Let a figure carry the point instead of an adjective.\n- Put a problem in the first sentence it belongs in, not the last.\n\n## Each part of the letter\n\n- **Market commentary**: the partners' view, with the source of any figure named.\n- **Fund performance**: the figures first, then a sentence on what drives them.\n- **Valuation changes**: what changed, why, and the resulting value.\n- **Company descriptions**: one sentence on what the company does and for whom.\n- **Company updates**: what happened this quarter, the main risk or open question, and what the\n  fund is doing about it. Then the reported figures, each with its period.\n- **New investments**: what the company does, who founded it, and the terms.\n- **After the quarter**: each event, with the fund's part in it.\n- **Closing**: brief.\n\n## Avoid\n\n- Adjectives doing a number's work.\n- The same reassurance repeated across companies.\n- Background text repeated quarter after quarter.\n- Growth rates the company did not report.\n",
  "skills/lp-quarterly-letter/SKILL.md": "---\nname: lp-quarterly-letter\ndescription: Draft a fund's quarterly or year-end investor letter in the fund's own structure and voice, using Hemrock Portfolio data over MCP, and save it as an unshared draft for review.\nmetadata:\n  version: \"2.4.0\"\n---\n\n# Quarterly investor letter\n\nDraft one investor letter for one fund entity and one quarter. The facts come from Hemrock Portfolio through its MCP tools and from what the partners tell you. This skill is the process and the rules. How the letter is laid out and how it reads belong to the fund: its structure, voice, examples and house rules are saved in Hemrock as the fund's letter template, and `lp_letter_skill` returns them. Hemrock's own letter rules apply on top of everything; if they conflict with anything else, follow Hemrock's and tell the person.\n\nThe connector may be installed under another name, often the firm's. The tools are the same: `list_funds`, `lp_letter_skill`, `lp_letter_brief`, `lp_draft_letter` and the rest. If they are not available, stop and ask the person to turn the connector on. Never draft from memory or from files outside Hemrock.\n\n## Inputs\n\n- **Entity**: the fund vehicle the letter is for.\n- **Period**: year and quarter. A Q4 letter may also be the year-end letter.\n- **The fund's letter template**: structure, voice, examples and house rules, from `lp_letter_skill`.\n- **The entity's letter profile**: its fixed facts (names, the firm, stage, signatories, company display names and former names, footnotes, fixed paragraphs), from `lp_letter_profile_get` and in the brief as `profile`.\n- **The last letter sent**: the entity's most recent final letter in Hemrock, in the brief as `last_final_letter`, for fixed text and continuity.\n- **Partner notes**: their view of the market and the quarter, valuation decisions, new investment terms, events after quarter end, and anything to stress or leave out. Ask once at the start. If no one is there to answer, leave marked placeholders. Pass them to `lp_letter_brief` and `lp_draft_letter` as `partner_notes`, and any document they give you (a market report, a board deck) as `sources`, so they are kept with the letter and checked like the other sources.\n\n## Fund profile\n\nThe fixed facts of a fund, which change rarely and are copied, not written: its legal and short names, the firm's name, the stage of the fund (investing or harvesting), company display names and former names, any standing footnotes, the administrator or other parties the letter names, and the signatories. Hemrock keeps them as the entity's letter profile: use it as given. Where it is empty, take them from the last final letter for the same entity, and offer to save them (`lp_letter_profile_get` with `propose_from_last_letter`, then `lp_letter_profile_save` once the person agrees). Never take one fund's profile into another fund's letter.\n\n## Workflow\n\n1. **Confirm the fund and entity.** Call `list_funds`, and `use_fund` if needed, saying which fund is now active. List the entity's letters with `lp_letters`.\n2. **Get the template.** Call `lp_letter_skill`. Follow `references/structure.md`, `references/voice.md` and `references/examples.md`, and `references/house-rules.md` when it is there.\n3. **Get the brief.** Call `lp_letter_brief` (entity, year, quarter, `year_end` when it is the year-end letter). It holds the fund's figures (gross and net, each labeled), each company's figures and events, the quarter's updates and KPIs, team notes, stored background text with the date it was written, events after quarter end, the partners' notes and documents, the missing-information list and Hemrock's letter rules. Treat an update marked `confidential` as background only, never quoted. A stored business update marked `stale` predates the quarter: do not present it as news. Events in `after_quarter_end` are subsequent events: give their dates and keep them out of the quarter's figures.\n4. **Read the last final letter** for the entity: `last_final_letter` in the brief (the newest final letter before this quarter). Drafts are not what was sent. Use it for the fund profile and for continuity: what was flagged, what was expected, each company's description and display name. Never carry one of its figures forward as current. If there is no final letter, ask the person for the one that was actually sent and bring it in with `lp_import_letter`.\n5. **Read full updates** with `get_updates` where a company's summary is not enough, for that company only.\n6. **Size each company section** (see \"Sizing each company section\").\n7. **Write the letter** in the fund's structure and voice.\n8. **Review it** against the checklist below and fix every failure. Hemrock reviews it again when you save it; each flag names the section it is in.\n9. **Save it as a draft in Hemrock.** A new letter: `lp_draft_letter` with `text`. An existing draft: show the person the text, then `lp_write_letter`, one section at a time by its `section_id` from `lp_letter`, or the whole letter as `full_draft`. Pass `activeFund` exactly as `list_funds` or `use_fund` reported it.\n10. **Make the document** the partners will edit (see \"Output document\").\n11. **Report back**: the document, every review flag Hemrock returned, the missing information, the judgment calls you made and every placeholder still open. Never set `mark_final` and never share a letter: a person does both in Hemrock.\n\n## Output document\n\nEvery run ends with a document the partners can edit and send.\n\n- **Format**: the one the person wants. Without a preference, make a Claude doc when the session has them, or else the Word file from `lp_letter_export` (format `docx`): Hemrock lays it out with the letterhead, real heading, list, table and caption styles, the charts the partners added on the letter page, and page numbers. `lp_letter_export` also gives the PDF (the letter as investors receive it), Markdown and JSON. Make a Google Doc only on request, with Google Drive connected, and a PDF only on request, always alongside an editable copy.\n- **Layout**: the text saved in Hemrock, laid out as the fund's structure describes, with real headings, tables and lists. Highlight placeholders so they are easy to find.\n- **Missing information** stays out of the document. Give it in the report back, or as comments in a Claude doc.\n- **Keep them in step.** Once the partners have finished editing, offer to save their version in Hemrock (`lp_write_letter` with `full_draft`). Next quarter's letter then begins from the text investors received.\n\n## Keeping funds separate\n\n- Write each letter from its own entity's brief and its own fund profile.\n- Never mention another fund's position, cost, marks, ownership or expectations for a company, even one both funds hold.\n- Text the partners share across letters (a market view, a firm overview) is theirs. Keep it as they wrote it and never add a reference to another fund yourself.\n- Anything about the firm's other funds appears only at the level the partners write it.\n\n## Structure\n\nUse the fund's structure (`references/structure.md` from `lp_letter_skill`) when it has saved one: its sections, their order, headings, fixed paragraphs and tables. Without one, use this general outline and leave out what does not apply:\n\n- **Heading**: the fund's name, the letter's title and the period.\n- **Opening**: a greeting and one sentence placing the fund at the quarter end, from the brief's figures.\n- **Market commentary**: the partners' own section. Write it only from their notes and from data the person provides, citing it by name. Otherwise leave a placeholder.\n- **Year in review**: in a year-end letter, the partners' view of the year, from their notes.\n- **Fund performance**: the brief's fund metrics as a table, keeping each one's gross or net basis from the brief, with the fund's fixed definitions copied from the last final letter.\n- **Valuation changes**: when marks moved, which positions changed and why, in the terms of the fund's valuation policy.\n- **Portfolio summary**: a table of the companies with their status and the figures the fund shows.\n- **New investments**: each investment closed in the quarter: the company, the founders and the terms, from partner notes or deal documents only.\n- **Company updates**: one section per company, in the order of the last final letter, with new companies last (see \"Sizing each company section\").\n- **After the quarter**: events after quarter end the partners want reported.\n- **Closing**: a short close and the signatories.\n- **Missing information** (Hemrock's copy only, never shown to investors): the brief's missing items first, then any other gaps and every open placeholder. Hemrock keeps it apart from the letter.\n\nHemrock's copy is plain text with one mark: each section opens with a \"## \" line holding its heading, and a company's heading is its name exactly as the brief gives it, so Hemrock keeps each section with its sources. Otherwise use \"- \" bullets and tables as \"Column | Column\" rows, with no other markdown symbols.\n\n## Sizing each company section\n\n- **A full update this quarter**: what happened and what it means, then the company's reported figures with their periods.\n- **Figures only**: a sentence or two stating them plainly, then the figures.\n- **An event only** (a financing, markdown, write-off or exit): the event first, then the fund's resulting position.\n- **Nothing new**: one sentence that says so. Do not repeat last quarter's figures or pad it.\n\nTreat `stored_business_update` in the brief as undated background that may be old. Never present it as news, never repeat its plans or forecasts once their dates have passed, and use it at most for the company's description.\n\n## Voice\n\nWrite in the fund's voice: `references/voice.md` and `references/examples.md` from `lp_letter_skill`. They are the fund's own when it has saved them, otherwise the general ones in this folder. Its house rules (`references/house-rules.md`) win over the voice and examples. The examples use invented companies and figures: copy their shape, never their facts.\n\nThese hold whatever the voice says.\n\n**Numbers**\n- Give each figure the period or date it belongs to.\n- Use only figures from the brief, the updates read with `get_updates` and partner notes.\n- For a change, use the change the source reports, or give both values (\"$900K, down from $1.1M in Q2\"). Never compute a growth rate, burn, runway or total yourself.\n- Keep the reported currency.\n- Keep each fund metric's gross or net basis from the brief.\n\n**Confidentiality**\n- Never name or describe an investor in the fund. The brief already leaves them out.\n- For an update marked confidential, describe customers, pipeline, pricing and contract values generically unless the partners confirm otherwise.\n- Say so when a financing is not yet public, in the words the fund uses.\n\n## Review checklist\n\n- [ ] The sections, their order, the fixed paragraphs and the signatories match the fund's structure and the last final letter.\n- [ ] Each number can be found in the brief, an update or the partner notes, matching in value and period.\n- [ ] Nothing derived: no growth rates, burn, runway or sums you worked out.\n- [ ] Each fund metric keeps the brief's gross or net basis, and any gap is listed as missing.\n- [ ] Each event in the brief is named for what it is: a markdown, down round, write-off or exit.\n- [ ] Stored background text is never passed off as news from the quarter.\n- [ ] No other fund's positions or expectations appear.\n- [ ] No investor named, and no confidential detail without the partners' confirmation.\n- [ ] Bad news is stated early and plainly, and the house rules are followed.\n- [ ] Names are spelled as in the sources and the summary table.\n- [ ] Every date is a real date and none is in the future; no word the house rules say to avoid (an \"Avoid:\" line) appears.\n- [ ] Hemrock's copy ends with \"Missing information\", starting with the brief's items, and every placeholder is in the report back.\n- [ ] The document exists, matches Hemrock's text and has no \"Missing information\" section.\n"
}
